changeSet.sql:
DELETE FROM asset_uid_history
WHERE asset_id IN (SELECT id FROM asset WHERE asset_type = 'STRUCTURE');

DELETE FROM asset_reference
WHERE from_asset_id IN (SELECT id FROM asset WHERE asset_type = 'STRUCTURE')
   OR to_asset_id IN (SELECT id FROM asset WHERE asset_type = 'STRUCTURE');

DELETE FROM asset_version
WHERE asset_id IN (SELECT id FROM asset WHERE asset_type = 'STRUCTURE');

DELETE FROM asset
WHERE asset_type = 'STRUCTURE';
